# make_logger_overlay_blender.py — run in Blender (Scripting > New > paste > Run)
# Builds the logger-overlay guides on the (Y-up imported) LiDAR terrain.
# ENU (x,y,z) -> Blender (x,-z,y).
import bpy
import numpy as np

def mk_curve(name, pts, cyclic, rgb):
    cu = bpy.data.curves.new(name, type='CURVE'); cu.dimensions='3D'
    cu.bevel_depth = 0.6                      # visible ribbon-ish line
    sp = cu.splines.new('POLY'); sp.points.add(len(pts)-1)
    for i,(x,yv,z) in enumerate(pts):
        sp.points[i].co = (x, -z, yv, 1.0)
    sp.use_cyclic_u = cyclic
    ob = bpy.data.objects.new(name, cu); bpy.context.collection.objects.link(ob)
    mat = bpy.data.materials.new(name+"_m"); mat.use_nodes=True
    mat.diffuse_color = (*rgb, 1)             # SOLID-shading color (separate from
                                               # the node tree below; without this
                                               # every curve looks the same grey in
                                               # Solid mode even though the node
                                               # tree colors are correct)
    mat.node_tree.nodes["Principled BSDF"].inputs["Base Color"].default_value=(*rgb,1)
    mat.node_tree.nodes["Principled BSDF"].inputs["Emission Color"].default_value=(*rgb,1)
    try: mat.node_tree.nodes["Principled BSDF"].inputs["Emission Strength"].default_value=1.0
    except Exception: pass
    cu.materials.append(mat)
    return ob

